-- 대성 공판장: 2026-10-26 검수된 상품만 교체. 기존 거래 참조는 보존합니다.
-- 181개 상품 그룹 / 229개 판매 옵션 / 38개 행 보류.
begin;

-- Restore the public catalogue grant; existing RLS exposes active approved listings only.
grant select on public.offerings to anon;

create or replace function public.market_product_minimum(details jsonb)
returns integer language sql immutable set search_path = '' as $$
  select case when coalesce(details->>'minimumOrderQuantity','') ~ '^[1-9][0-9]{0,3}$'
    then least(1000,(details->>'minimumOrderQuantity')::integer) else 1 end;
$$;

create or replace function public.market_product_step(details jsonb)
returns integer language sql immutable set search_path = '' as $$
  select case when coalesce(details->>'quantityStep','') ~ '^[1-9][0-9]{0,3}$'
    then least(1000,(details->>'quantityStep')::integer) else 1 end;
$$;

create or replace function public.enforce_market_checkout_quantities()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  item record;
  minimum integer;
  step integer;
begin
  if new.kind <> 'market' then return new; end if;
  for item in
    select o.name,o.detail_sections,sum(x.quantity)::bigint as quantity
    from jsonb_to_recordset(case when jsonb_typeof(new.draft->'items')='array' then new.draft->'items' else '[]'::jsonb end)
      as x(offering_id uuid,quantity integer)
    join public.offerings o on o.id=x.offering_id
    group by o.id,o.name,o.detail_sections
  loop
    minimum := public.market_product_minimum(item.detail_sections);
    step := public.market_product_step(item.detail_sections);
    if item.quantity < minimum or mod(item.quantity-minimum,step) <> 0 then
      raise exception using message = format('%s: 최소 %s%s, 이후 %s%s 단위로 주문해주세요.',
        item.name,minimum,coalesce(item.detail_sections->>'quantityUnit','개'),
        step,coalesce(item.detail_sections->>'quantityUnit','개'));
    end if;
  end loop;
  return new;
end;
$$;

revoke all on function public.enforce_market_checkout_quantities() from public;
drop trigger if exists payment_intents_market_quantity_guard on public.payment_intents;
create trigger payment_intents_market_quantity_guard before insert on public.payment_intents
for each row execute function public.enforce_market_checkout_quantities();


