연출 이미지이며 주문 중량과 다릅니다. 원산지와 손질 형태는 수령 전 판매자에게 확인해주세요.","importSource":"google-sheet:1EpOa9nYiHjQLRyVAToeY01I-8HyHaFSBY8y9C41CYV0:gid-479454213","sourceSheetRow":276,"sourceSheetRows":[276],"sourcePriceText":"1kg당 31800 / 수입냉동  18500","photoStatus":"제공 원본 AI 보정","imageStyle":"product-photo","catalogVersion":"20261026","minimumOrderQuantity":5,"quantityStep":1,"quantityUnit":"kg","temperature":"수입 냉동","imageIsIllustrative":true},"origin":"수입산 · 세부 원산지는 판매자에게 확인해주세요.","nutrition_info":{"description":"상품 포장지의 영양정보를 확인해주세요."},"is_alcohol":false,"stock_quantity":null}]$catalog$::jsonb;
  expected integer := 229;
  actual integer;
begin
  perform pg_advisory_xact_lock(hashtext('motf-daesung-catalog-import'));
  perform 1 from public.businesses where id=target and business_type='market' and approval_status='approved' and regexp_replace(business_name,'\s','','g')='대성공판장' for update;
  if not found then raise exception '승인된 대성 공판장 업장이 일치하지 않습니다.'; end if;
  if jsonb_array_length(payload)<>expected then raise exception '상품 개수 검증 실패'; end if;
  if exists(select 1 from jsonb_array_elements(payload) p where (p->>'price')::integer<=0 or p->>'image_url' is null or p->'detail_sections'->>'productGroupKey' is null) then raise exception '상품 필수정보 검증 실패'; end if;
  if exists(select 1 from jsonb_array_elements(payload) p join public.offerings o on o.id=(p->>'id')::uuid where o.business_id<>target) then raise exception '다른 업장의 상품 ID와 충돌합니다.'; end if;
  update public.offerings set is_active=false,updated_at=now() where business_id=target and is_active;
  insert into public.offerings(id,business_id,name,description,price,is_active,unit,category,image_url,image_urls,sort_order,feature_summary,amenity_details,detail_sections,origin,nutrition_info,is_alcohol,stock_quantity,updated_at)
  select p.id,target,p.name,p.description,p.price,true,p.unit,p.category,p.image_url,p.image_urls,p.sort_order,p.feature_summary,p.amenity_details,p.detail_sections,p.origin,p.nutrition_info,p.is_alcohol,p.stock_quantity,now()
  from jsonb_populate_recordset(null::public.offerings,payload) p
  on conflict(id) do update set name=excluded.name,description=excluded.description,price=excluded.price,is_active=true,unit=excluded.unit,category=excluded.category,image_url=excluded.image_url,image_urls=excluded.image_urls,sort_order=excluded.sort_order,feature_summary=excluded.feature_summary,amenity_details=excluded.amenity_details,detail_sections=excluded.detail_sections,origin=excluded.origin,nutrition_info=excluded.nutrition_info,is_alcohol=excluded.is_alcohol,stock_quantity=excluded.stock_quantity,updated_at=now();
  update public.businesses set cover_image_url='https://motf.co.kr/assets/market/daesung/20261026/storefront-close.webp',gallery_image_urls=array['https://motf.co.kr/assets/market/daesung/20261026/storefront-close.webp','https://motf.co.kr/assets/market/daesung/20261026/storefront-wide.webp'],updated_at=now() where id=target;
  select count(*) into actual from public.offerings where business_id=target and is_active;
  if actual<>expected then raise exception '등록 후 개수 불일치: % / %',actual,expected; end if;
end;
$import$;
commit;

select b.business_name,count(*) as active_variants,count(distinct o.detail_sections->>'productGroupKey') as product_groups
from public.offerings o join public.businesses b on b.id=o.business_id
where o.business_id='d5513697-7341-4cc6-a16b-781caf6b902d' and o.is_active group by b.business_name;
